<?php
/**
 * Keccak-f[1600] and the SHAKE128 / SHAKE256 extendable-output functions (FIPS 202), in pure PHP on native
 * 64-bit integers. Lanes are PHP ints; values with the top bit set are simply negative, which is fine because
 * only XOR, AND, NOT and shifts touch them (the right shift is arithmetic, so rotations mask the sign bits off).
 *
 * The round body is generated by tests/pq/codegen.php; do not edit it by hand.
 */

namespace HR\Platform\PQ;

if ( ! defined( 'ABSPATH' ) ) exit;

final class Keccak {

    /** Round constants. Written as (hi << 32) | lo so that none of them overflows into a float literal. */
    private const RC = array(
        ( 0x00000000 << 32 ) | 0x00000001, ( 0x00000000 << 32 ) | 0x00008082, ( 0x80000000 << 32 ) | 0x0000808A,
        ( 0x80000000 << 32 ) | 0x80008000, ( 0x00000000 << 32 ) | 0x0000808B, ( 0x00000000 << 32 ) | 0x80000001,
        ( 0x80000000 << 32 ) | 0x80008081, ( 0x80000000 << 32 ) | 0x00008009, ( 0x00000000 << 32 ) | 0x0000008A,
        ( 0x00000000 << 32 ) | 0x00000088, ( 0x00000000 << 32 ) | 0x80008009, ( 0x00000000 << 32 ) | 0x8000000A,
        ( 0x00000000 << 32 ) | 0x8000808B, ( 0x80000000 << 32 ) | 0x0000008B, ( 0x80000000 << 32 ) | 0x00008089,
        ( 0x80000000 << 32 ) | 0x00008003, ( 0x80000000 << 32 ) | 0x00008002, ( 0x80000000 << 32 ) | 0x00000080,
        ( 0x00000000 << 32 ) | 0x0000800A, ( 0x80000000 << 32 ) | 0x8000000A, ( 0x80000000 << 32 ) | 0x80008081,
        ( 0x80000000 << 32 ) | 0x00008080, ( 0x00000000 << 32 ) | 0x80000001, ( 0x80000000 << 32 ) | 0x80008008,
    );

    /** SHAKE128 rate in bytes. */
    public const RATE128 = 168;
    /** SHAKE256 rate in bytes. */
    public const RATE256 = 136;

    /** SHAKE128 of $in, $len bytes of output. */
    public static function shake128( string $in, int $len ): string {
        return ( new Xof( self::RATE128, $in ) )->read( $len );
    }

    /** SHAKE256 of $in, $len bytes of output. */
    public static function shake256( string $in, int $len ): string {
        return ( new Xof( self::RATE256, $in ) )->read( $len );
    }

    /**
     * The permutation. Takes and returns the 25-lane state (index x + 5y).
     *
     * @param int[] $s
     * @return int[]
     */
    public static function f1600( array $s ): array {
        [ $s0, $s1, $s2, $s3, $s4, $s5, $s6, $s7, $s8, $s9, $s10, $s11, $s12,
          $s13, $s14, $s15, $s16, $s17, $s18, $s19, $s20, $s21, $s22, $s23, $s24 ] = $s;
        foreach ( self::RC as $rc ) {
            // BEGIN GENERATED keccak-round
            $c0 = $s0 ^ $s5 ^ $s10 ^ $s15 ^ $s20;
            $c1 = $s1 ^ $s6 ^ $s11 ^ $s16 ^ $s21;
            $c2 = $s2 ^ $s7 ^ $s12 ^ $s17 ^ $s22;
            $c3 = $s3 ^ $s8 ^ $s13 ^ $s18 ^ $s23;
            $c4 = $s4 ^ $s9 ^ $s14 ^ $s19 ^ $s24;
            $d0 = $c4 ^ ( ( $c1 << 1 ) | ( ( $c1 >> 63 ) & 1 ) );
            $d1 = $c0 ^ ( ( $c2 << 1 ) | ( ( $c2 >> 63 ) & 1 ) );
            $d2 = $c1 ^ ( ( $c3 << 1 ) | ( ( $c3 >> 63 ) & 1 ) );
            $d3 = $c2 ^ ( ( $c4 << 1 ) | ( ( $c4 >> 63 ) & 1 ) );
            $d4 = $c3 ^ ( ( $c0 << 1 ) | ( ( $c0 >> 63 ) & 1 ) );
            $b0 = $s0 ^ $d0;
            $t = $s1 ^ $d1; $b10 = ( $t << 1 ) | ( ( $t >> 63 ) & 0x1 );
            $t = $s2 ^ $d2; $b20 = ( $t << 62 ) | ( ( $t >> 2 ) & 0x3FFFFFFFFFFFFFFF );
            $t = $s3 ^ $d3; $b5 = ( $t << 28 ) | ( ( $t >> 36 ) & 0xFFFFFFF );
            $t = $s4 ^ $d4; $b15 = ( $t << 27 ) | ( ( $t >> 37 ) & 0x7FFFFFF );
            $t = $s5 ^ $d0; $b16 = ( $t << 36 ) | ( ( $t >> 28 ) & 0xFFFFFFFFF );
            $t = $s6 ^ $d1; $b1 = ( $t << 44 ) | ( ( $t >> 20 ) & 0xFFFFFFFFFFF );
            $t = $s7 ^ $d2; $b11 = ( $t << 6 ) | ( ( $t >> 58 ) & 0x3F );
            $t = $s8 ^ $d3; $b21 = ( $t << 55 ) | ( ( $t >> 9 ) & 0x7FFFFFFFFFFFFF );
            $t = $s9 ^ $d4; $b6 = ( $t << 20 ) | ( ( $t >> 44 ) & 0xFFFFF );
            $t = $s10 ^ $d0; $b7 = ( $t << 3 ) | ( ( $t >> 61 ) & 0x7 );
            $t = $s11 ^ $d1; $b17 = ( $t << 10 ) | ( ( $t >> 54 ) & 0x3FF );
            $t = $s12 ^ $d2; $b2 = ( $t << 43 ) | ( ( $t >> 21 ) & 0x7FFFFFFFFFF );
            $t = $s13 ^ $d3; $b12 = ( $t << 25 ) | ( ( $t >> 39 ) & 0x1FFFFFF );
            $t = $s14 ^ $d4; $b22 = ( $t << 39 ) | ( ( $t >> 25 ) & 0x7FFFFFFFFF );
            $t = $s15 ^ $d0; $b23 = ( $t << 41 ) | ( ( $t >> 23 ) & 0x1FFFFFFFFFF );
            $t = $s16 ^ $d1; $b8 = ( $t << 45 ) | ( ( $t >> 19 ) & 0x1FFFFFFFFFFF );
            $t = $s17 ^ $d2; $b18 = ( $t << 15 ) | ( ( $t >> 49 ) & 0x7FFF );
            $t = $s18 ^ $d3; $b3 = ( $t << 21 ) | ( ( $t >> 43 ) & 0x1FFFFF );
            $t = $s19 ^ $d4; $b13 = ( $t << 8 ) | ( ( $t >> 56 ) & 0xFF );
            $t = $s20 ^ $d0; $b14 = ( $t << 18 ) | ( ( $t >> 46 ) & 0x3FFFF );
            $t = $s21 ^ $d1; $b24 = ( $t << 2 ) | ( ( $t >> 62 ) & 0x3 );
            $t = $s22 ^ $d2; $b9 = ( $t << 61 ) | ( ( $t >> 3 ) & 0x1FFFFFFFFFFFFFFF );
            $t = $s23 ^ $d3; $b19 = ( $t << 56 ) | ( ( $t >> 8 ) & 0xFFFFFFFFFFFFFF );
            $t = $s24 ^ $d4; $b4 = ( $t << 14 ) | ( ( $t >> 50 ) & 0x3FFF );
            $s0 = $b0 ^ ( ~$b1 & $b2 ) ^ $rc;
            $s1 = $b1 ^ ( ~$b2 & $b3 );
            $s2 = $b2 ^ ( ~$b3 & $b4 );
            $s3 = $b3 ^ ( ~$b4 & $b0 );
            $s4 = $b4 ^ ( ~$b0 & $b1 );
            $s5 = $b5 ^ ( ~$b6 & $b7 );
            $s6 = $b6 ^ ( ~$b7 & $b8 );
            $s7 = $b7 ^ ( ~$b8 & $b9 );
            $s8 = $b8 ^ ( ~$b9 & $b5 );
            $s9 = $b9 ^ ( ~$b5 & $b6 );
            $s10 = $b10 ^ ( ~$b11 & $b12 );
            $s11 = $b11 ^ ( ~$b12 & $b13 );
            $s12 = $b12 ^ ( ~$b13 & $b14 );
            $s13 = $b13 ^ ( ~$b14 & $b10 );
            $s14 = $b14 ^ ( ~$b10 & $b11 );
            $s15 = $b15 ^ ( ~$b16 & $b17 );
            $s16 = $b16 ^ ( ~$b17 & $b18 );
            $s17 = $b17 ^ ( ~$b18 & $b19 );
            $s18 = $b18 ^ ( ~$b19 & $b15 );
            $s19 = $b19 ^ ( ~$b15 & $b16 );
            $s20 = $b20 ^ ( ~$b21 & $b22 );
            $s21 = $b21 ^ ( ~$b22 & $b23 );
            $s22 = $b22 ^ ( ~$b23 & $b24 );
            $s23 = $b23 ^ ( ~$b24 & $b20 );
            $s24 = $b24 ^ ( ~$b20 & $b21 );            // END GENERATED keccak-round
        }
        return array( $s0, $s1, $s2, $s3, $s4, $s5, $s6, $s7, $s8, $s9, $s10, $s11, $s12,
            $s13, $s14, $s15, $s16, $s17, $s18, $s19, $s20, $s21, $s22, $s23, $s24 );
    }
}

/**
 * Incremental SHAKE reader: absorbs the whole input up front, then hands out output in any amounts.
 * Used for rejection sampling (ML-DSA ExpandA, ExpandS, SampleInBall), where the needed length is not known.
 */
final class Xof {

    /** @var int[] */
    private array $s;
    private int $rate;
    private bool $fresh = true;
    private string $buf = '';

    /** @param int $rate Keccak::RATE128 for SHAKE128, Keccak::RATE256 for SHAKE256. */
    public function __construct( int $rate, string $input ) {
        $this->rate = $rate;
        $lanes      = $rate >> 3;
        $fmt        = 'P' . $lanes;
        $s          = array_fill( 0, 25, 0 );
        $len        = strlen( $input );
        $off        = 0;
        for ( ; $len - $off >= $rate; $off += $rate ) {
            $w = unpack( $fmt, $input, $off );
            for ( $i = 0; $i < $lanes; $i++ ) {
                $s[ $i ] ^= $w[ $i + 1 ];
            }
            $s = Keccak::f1600( $s );
        }
        // Final block: SHAKE domain bits 1111 then pad10*1.
        $last          = substr( $input, $off ) . "\x1F" . str_repeat( "\0", $rate - ( $len - $off ) - 1 );
        $last[ $rate - 1 ] = chr( ord( $last[ $rate - 1 ] ) | 0x80 );
        $w = unpack( $fmt, $last );
        for ( $i = 0; $i < $lanes; $i++ ) {
            $s[ $i ] ^= $w[ $i + 1 ];
        }
        $this->s = Keccak::f1600( $s );
    }

    /** The next full block of output (rate bytes). Do not mix with read() on the same reader. */
    public function block(): string {
        if ( $this->fresh ) {
            $this->fresh = false;
        } else {
            $this->s = Keccak::f1600( $this->s );
        }
        $lanes = $this->rate >> 3;
        return pack( 'P' . $lanes, ...array_slice( $this->s, 0, $lanes ) );
    }

    /** The next $n bytes of output. */
    public function read( int $n ): string {
        while ( strlen( $this->buf ) < $n ) {
            $this->buf .= $this->block();
        }
        $out       = substr( $this->buf, 0, $n );
        $this->buf = (string) substr( $this->buf, $n );
        return $out;
    }

    /** Best-effort wipe of the sponge state (it can hold secret-derived bytes). */
    public function wipe(): void {
        $this->s = array_fill( 0, 25, 0 );
        if ( '' !== $this->buf && function_exists( 'sodium_memzero' ) ) {
            sodium_memzero( $this->buf );
        }
        $this->buf = '';
    }
}
